    <script>
      // 切换三线 Tabs 的逻辑
      window.switchBcTab = function(tabId, event) {
          if(event) event.stopPropagation();
          const wrapper = event.currentTarget.closest('.bc-page-2-content');
          
          // 切换 Tab 样式
          wrapper.querySelectorAll('.bc-tab').forEach(t => t.classList.remove('active'));
          event.currentTarget.classList.add('active');
          
          // 切换列表显示
          wrapper.querySelectorAll('.bc-list').forEach(l => l.classList.remove('active'));
          wrapper.querySelector('#bc-list-' + tabId).classList.add('active');
      };

      function showTip(message) {
        const existingTip = document.querySelector('.custom-tip-message');
        if (existingTip) {
          existingTip.remove();
        }

        const tip = document.createElement('div');
        tip.className = 'custom-tip-message';
        tip.style.cssText = `
          position: fixed; top: 20px; left: 50%; transform: translateX(-50%);
          background: rgba(2, 6, 17, 0.95); color: #1a75ff; padding: 10px 20px;
          font-size: 0.9em; font-weight: bold; z-index: 9999; border-radius: 4px;
          border: 1px solid #1a75ff;
          box-shadow: 0 8px 20px rgba(0, 0, 0, 0.8), 0 0 15px rgba(26, 117, 255, 0.4); 
          font-family: sans-serif; opacity: 0; transition: all 0.4s ease;
        `;
        tip.textContent = message;
        document.body.appendChild(tip);
        setTimeout(() => { tip.style.opacity = '1'; tip.style.top = '30px'; }, 10);
        setTimeout(() => {
          tip.style.opacity = '0';
          tip.style.top = '20px';
          setTimeout(() => tip.remove(), 400);
        }, 2200);
      }

      async function switchToOpening(openingId) {
        try {
          if (typeof getChatMessages !== 'function' || typeof setChatMessage !== 'function') {
            console.log(`模拟切换到开场白 ID: ${openingId}`);
            showTip(`✦ 模拟切换成功: 开场白 ${openingId}`);
            return;
          }
          const messages = await getChatMessages(0, { include_swipe: true });
          if (messages && messages.length > 0 && messages[0].swipes && messages[0].swipes.length >= openingId) {
            const content = messages[0].swipes[openingId - 1];
            await setChatMessage(content, 0, { swipe_id: openingId - 1, refresh: 'display_and_render_current' });
            showTip(`✦ 切换成功: 开场白 ${openingId}`);
          } else {
            showTip(`❌ 错误: 找不到开场白 ${openingId}`);
          }
        } catch (error) {
          showTip(`❌ 切换失败: ${error.message}`);
        }
      }
    </script>
